import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/WhatDoPositionEmbeddingsLearn.html","title":"WhatDoPositionEmbeddingsLearn","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.85,"words":554},"filePathRelative":"WhatDoPositionEmbeddingsLearn.md"}`),a={name:`WhatDoPositionEmbeddingsLearn.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="whatdopositionembeddingslearn" tabindex="-1"><a class="header-anchor" href="#whatdopositionembeddingslearn"><span>WhatDoPositionEmbeddingsLearn</span></a></h1><p><a href="./PositionEmbeddings.html">PositionEmbeddings</a>の<a href="./論文.html">論文</a>。</p><ul><li><a href="https://arxiv.org/abs/2010.04903" target="_blank" rel="noopener noreferrer">arxiv:2010.04903 What Do Position Embeddings Learn? An Empirical Study of Pre-Trained Language Model Positional Encoding</a></li></ul><p>Pre-trainedモデルのpositional embeddingsが実際に何を学習しているかとか、様々なNLPタスクへのパフォーマンスの影響を実証的に調べる。</p><h2 id="実験対象" tabindex="-1"><a class="header-anchor" href="#実験対象"><span>実験対象</span></a></h2><ul><li>BERTのEncoder</li><li>RoBERTaのEncoder</li><li>GPT-2のDecoder</li><li>sinusodial (Transformerの、学習ではない算術式）</li></ul><h2 id="_4章、embeddingsをフィーチャーとみた逆象の評価" tabindex="-1"><a class="header-anchor" href="#_4章、embeddingsをフィーチャーとみた逆象の評価"><span>4章、embeddingsをフィーチャーとみた逆象の評価</span></a></h2><p>Pre-trainedなembeddingsに実際にどういう値が入っているかを、逆象を機械学習で学習させてみて調べてみる章。</p><h3 id="_4-1-1-絶対位置の逆写像の線形回帰" tabindex="-1"><a class="header-anchor" href="#_4-1-1-絶対位置の逆写像の線形回帰"><span>4.1.1 絶対位置の逆写像の線形回帰</span></a></h3><p>それぞれのembeddingの値から絶対位置への逆写像を線形回帰で作ってみる、という実験。 GPT-2は1024トークンを512に揃えるべく再学習したとか。</p><p>結果はテーブル1（以下に転載）。</p><table><thead><tr><th>PE</th><th>MAE</th></tr></thead><tbody><tr><td>BERT</td><td>34.14</td></tr><tr><td>RoBERTa</td><td>6.06</td></tr><tr><td>GPT-2</td><td>1.03</td></tr><tr><td>sinusoid</td><td>0.0</td></tr></tbody></table><p>BERTのembeddingsはあんまり絶対位置の情報はもってない雰囲気ではある。</p><h3 id="実験のインプットが良く分からない" tabindex="-1"><a class="header-anchor" href="#実験のインプットが良く分からない"><span>実験のインプットが良く分からない</span></a></h3><p>普通に考えると単にembeddingから逆象を学習するだけなら単なるルックアップテーブルで完全に正解してしまうだろうから、 入力は通常のトークンと足したものになっている実際の設定の方が良さそうだが、そうした記述はない。</p><p>512個のデータポイントしかない、と言っているから、単にembeddingの400個くらいでトレーニングして残りの100個くらいをテストセットとする、みたいな話なのかなぁ。</p><p>5-fold cross validationがうんたら、とか言っているのでそうっぽいか？</p><p>ただそうだとするとこの実験はちょっと知りたい事を調べられているか疑問な部分もあるな。 別に512個の中に、何らかの未知の対応を予想出来る関数形がある必要は無くて、単にlookupでもちゃんと逆象が作れればそれでいいはずだ。 493番目のembeddingsから494番目のembeddingsが予想出来る必要はないように思う。</p><h3 id="_4-1-2-相対位置の大小のロジスティック回帰" tabindex="-1"><a class="header-anchor" href="#_4-1-2-相対位置の大小のロジスティック回帰"><span>4.1.2 相対位置の大小のロジスティック回帰</span></a></h3><p>相対位置、つまり距離の逆写像が分かるか、という問題は、試したら全然わからないというのが答えらしい（詳細は載ってない）。</p><p>そこでもっと簡単な、どちらのトークンが先にでているか、というのを判定するロジスティック回帰を試してみた、というのが実験4.1.2で、結果は以下のテーブル2。</p><table><thead><tr><th>PE</th><th>Error Rate</th></tr></thead><tbody><tr><td>BERT</td><td>19.72%</td></tr><tr><td>RoBERTa</td><td>7.23%</td></tr><tr><td>GPT-2</td><td>1.56%</td></tr><tr><td>sinusoid</td><td>5.08%</td></tr></tbody></table><h3 id="_4-3-1-pre-trainのobjectiveの違い" tabindex="-1"><a class="header-anchor" href="#_4-3-1-pre-trainのobjectiveの違い"><span>4.3.1 Pre-TrainのObjectiveの違い</span></a></h3><p>BERTとRoBERTaはmasked language modelなので周辺の単語が使える。一方Decoderはlanguage modelの対数尤度の和がロスとなるので、1単語ずつ見ていくため、 より1方向の位置に依存しているように思える。</p><h2 id="_5章、実証実験" tabindex="-1"><a class="header-anchor" href="#_5章、実証実験"><span>5章、実証実験</span></a></h2><p>実際にNLPタスクに対してそれぞれのembeddingsを使って、　適当なTransformer（タスクごとに別もの）をつなげていろいろな問題を解かせる。</p><h3 id="_5-1-テキスト分類" tabindex="-1"><a class="header-anchor" href="#_5-1-テキスト分類"><span>5.1 テキスト分類</span></a></h3><p>テキストを与えて分類する。これはhidden stateにとって前の全入力を見れるので、より絶対位置が大切になる、と論文では述べられている。</p><p>使うTransformerは単純な1レイヤーのTransformer（マルチヘッド+FF）。</p><p>テーブル3を見ると、sinusoidが優秀ではあるが、全体的に差は結構小さい。しかも長さが短い時はむしろBERTのスコアの方が良かったりする。 長くなるほど4章の分析と整合的になる、というのはまぁそうかもしれないが、ちょっと単に結果にあうものを引っ張ってしまっているリスクがあるよなぁ。</p><h3 id="_5-2-言語モデル" tabindex="-1"><a class="header-anchor" href="#_5-2-言語モデル"><span>5.2 言語モデル</span></a></h3><p>Wikitext-2とWikitext-103というデータセットで言語モデル的なタスクのperplexityを調べている。両者のデータセットは2millionトークン、103millionトークンという違いらしい。</p><p>ただ良く分からないのが、それぞれに対してMasked Language ModelとAutoregressive LM (前のトークンのinference結果を使って次を予想する通常の奴）の別の実験を行っている。 これでは両者の比較にならないのでは？</p><p>さらに良く分からないskip position attackとかいって位置の所に変な値を掛けて結果がどう落ちるかとか調べている。かなり謎。</p><p>普通に同じモデルでautoregressive LMを調べれば良いのでは？という気がするが…</p><p>うさんくさいので軽く表を見て飛ばす。</p><h3 id="_5-3-翻訳タスク" tabindex="-1"><a class="header-anchor" href="#_5-3-翻訳タスク"><span>5.3 翻訳タスク</span></a></h3><p>Encoder-Decoderモデルで双方6レイヤーでBPE使っているモデルでNMTをしてみる、という実験。</p><p>EncoderとDecoderにそれぞれいろんなposition embeddingsを試すのはいいのだが、何故かsinusoidがない。なんでやねん。</p><p>スコア的にはBERTが一番良い、けれど長いテキストに関してはGPT-2が良いよ、みたいな結果だが、 これも微妙だなぁ。</p><h2 id="全体的には微妙な論文だが4章は参考になる" tabindex="-1"><a class="header-anchor" href="#全体的には微妙な論文だが4章は参考になる"><span>全体的には微妙な論文だが4章は参考になる</span></a></h2><p>実証的な結果はなんだかな〜という内容だが、4章の話は参考にはなるな、という感じ。 興味深いトピックをいまいちなやり方で研究した論文という感じ。</p>`,42)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};